const requestLogger = (req, res, next) => {
  const start = Date.now();

  // Option A
  next();
  const duration = Date.now() - start;
  console.log(`Duration: ${duration}ms`);

  // Option B
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`Duration: ${duration}ms`);
  });
  next();
};

